<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from "vue"; import type { ResolvedMode, ThemeDefinition, TokenPath } from "@oriatheme/core";
const props = defineProps<{ mode: ResolvedMode; draft: ThemeDefinition; open: boolean }>(); const emit = defineEmits<{ close: [] }>(); const expanded = ref(false); const drag = ref(0); let gesture: { y: number; time: number } | undefined;
const style = computed(() => { const tokens = props.draft.modes[props.mode]; const token = (name: string) => tokens[name as TokenPath]; return { "--preview-bg": String(token("color.bg")), "--preview-fg": String(token("color.fg")), "--preview-surface": String(token("color.surface")), "--preview-primary": String(token("color.primary")), "--preview-radius": `calc(${String(token("radius"))} * 2)`, "--oria-editor-sheet-drag": `${drag.value}px` }; });
const down = (event: PointerEvent) => { (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId); gesture = { y: event.clientY, time: event.timeStamp }; drag.value = 0; }; const move = (event: PointerEvent) => { if (gesture) drag.value = Math.max(0, event.clientY - gesture.y); }; const up = (event: PointerEvent) => { if (!gesture) return; const velocity = (event.clientY - gesture.y) / Math.max(1, event.timeStamp - gesture.time) * 1000; const projected = drag.value + velocity * .18; gesture = undefined; drag.value = 0; if (projected > 110) emit("close"); };
const escape = (event: KeyboardEvent) => { if (props.open && event.key === "Escape") emit("close"); }; onMounted(() => globalThis.addEventListener("keydown", escape)); onUnmounted(() => globalThis.removeEventListener("keydown", escape));
</script>
<template><aside data-oria-editor-preview :data-open="open" :data-expanded="expanded" :aria-label="`${mode} preview`" :style="style"><div data-oria-editor-sheet-bar><button type="button" aria-label="Drag preview sheet" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up"><i /></button><button type="button" @click="expanded = !expanded">{{ expanded ? 'Compact' : 'Expand' }}</button><button type="button" aria-label="Close preview" @click="emit('close')">×</button></div><div><small>Live preview · {{ mode }}</small><h2>Design that feels at home.</h2><p>Every valid change arrives atomically while the editor stays steady.</p><button type="button">Primary action</button><span>Secondary detail</span></div></aside></template>
